import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.orders.api.OrderFacade;
import java.time.Duration;
import java.time.Instant;
import org.junit.jupiter.api.Test;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;

class OrderExpiryTest {

    @Test
    void onlyPlacedOrdersOlderThanThirtyDaysAreCancelled() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            Instant now = Instant.now();
            Instant old = now.minus(Duration.ofDays(31));
            Instant recent = now.minus(Duration.ofDays(29));

            String stalePlaced = orders.place("c-1", Money.pln(100), old);
            String staleConfirmed = orders.place("c-2", Money.pln(100), old);
            orders.confirm(staleConfirmed);
            String freshPlaced = orders.place("c-3", Money.pln(100), recent);

            assertEquals(1, orders.expireStale());

            assertEquals("CANCELLED", orders.summary(stalePlaced).status());
            assertEquals("CONFIRMED", orders.summary(staleConfirmed).status());
            assertEquals("PLACED", orders.summary(freshPlaced).status());
            assertEquals(0, orders.expireStale());
        }
    }
}
}
